import { HttpError, paginate, type Page, type SourceContext } from '@chkit/plugin-ingest'
import { z } from 'zod'

import { slackReaderConfigSchema, type SlackReaderConfig } from './config.js'

export type MessageMethod = 'conversations.history' | 'conversations.replies'
interface CollectionMetadata { hasMore: boolean; cursorExpired?: true }
type CollectionPages<TItem> = AsyncGenerator<Page<TItem, string, CollectionMetadata>, void, void>
export type SlackSettings = Omit<z.output<typeof slackReaderConfigSchema>, 'token'>

export interface SlackClient {
  settings: SlackSettings
  workspace(): Promise<string>
  conversations(): CollectionPages<SlackEntity>
  users(): CollectionPages<SlackEntity>
  messages(method: MessageMethod, query: Record<string, string>): CollectionPages<SlackMessage>
}

type Method = 'auth.test' | 'conversations.list' | 'users.list' | MessageMethod
type Call = (method: Method, query: Record<string, string>) => Promise<SlackPayload>

interface CollectionRequest<TItem> {
  method: Exclude<Method, 'auth.test'>
  field: 'channels' | 'members' | 'messages'
  item: z.ZodType<TItem>
  limit: number
  query?: Record<string, string>
  boundary?: (items: readonly TItem[], hasMore: boolean) => boolean
}

const slackId = z.string().refine((value) => value.trim() !== '', 'must not be blank')
const slackTs = z.string().regex(/^\d+\.\d+$/, 'must be an unmodified decimal timestamp string')
const slackEntity = z.looseObject({ id: slackId })
const slackMessage = z.looseObject({ ts: slackTs, thread_ts: slackTs.optional(), reply_count: z.int().min(0).optional() })
const workspace = z.looseObject({ team_id: slackId })
const envelope = z.looseObject({ ok: z.boolean(), error: z.string().optional(), needed: z.string().optional() })
const pageEnvelope = z.looseObject({
  has_more: z.boolean().optional(),
  response_metadata: z.looseObject({ next_cursor: z.string().nullish() }).optional(),
})
const transientErrors = new Set(['internal_error', 'fatal_error', 'service_unavailable', 'request_timeout'])

export type SlackEntity = z.infer<typeof slackEntity>
export type SlackMessage = z.infer<typeof slackMessage>
type SlackPayload = z.infer<typeof envelope>

export function createSlackClient(context: SourceContext, config: SlackReaderConfig): SlackClient {
  const { token, ...settings } = slackReaderConfigSchema.parse(config)
  const call: Call = async (method, query) => {
    const url = new URL(`https://slack.com/api/${method}`)
    for (const [key, value] of Object.entries(query)) url.searchParams.set(key, value)
    const response = await context.fetch(url, {
      method: method === 'auth.test' ? 'POST' : 'GET',
      headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' },
      redirect: 'error',
    })
    return readPayload(method, response)
  }
  return {
    settings,
    workspace: () => context.attempt(async () => workspace.parse(await call('auth.test', {})).team_id, { label: 'POST /api/auth.test' }),
    conversations: () => selectConversations(readCollection(context, call, {
      method: 'conversations.list', field: 'channels', item: slackEntity, limit: settings.pageSize,
      query: { types: settings.conversationTypes.join(','), exclude_archived: 'false' },
    }), settings.channels),
    users: () => readCollection(context, call, { method: 'users.list', field: 'members', item: slackEntity, limit: settings.pageSize }),
    messages: (method, query) => readCollection(context, call, {
      method, field: 'messages', item: slackMessage, limit: settings.messagePageSize, query,
      boundary: (items, hasMore) => !hasMore || items.some((item) => method !== 'conversations.replies' || item.ts !== query.ts),
    }),
  }
}

function readCollection<TItem>(context: SourceContext, call: Call, request: CollectionRequest<TItem>): CollectionPages<TItem> {
  return paginate({
    context, label: `GET /api/${request.method}`,
    fetchPage: async (cursor: string | undefined): Promise<Page<TItem, string, CollectionMetadata>> => {
      const payload = await call(request.method, { ...request.query, limit: String(request.limit), ...(cursor ? { cursor } : {}) })
      if (payload.error === 'invalid_cursor') {
        if (!request.boundary) throw new Error(`Slack ${request.method} pagination cursor expired.`)
        return { items: [], next: undefined, metadata: { hasMore: false, cursorExpired: true } }
      }
      const page = pageEnvelope.parse(payload)
      const items = z.array(request.item).parse(payload[request.field])
      const next = page.response_metadata?.next_cursor?.trim() ?? ''
      const metadata = { hasMore: page.has_more === true || next.length > 0 }
      if (!request.boundary) {
        if (page.has_more === true && !next) throw new Error(`Slack ${request.method} reports more data without a pagination cursor; refusing an incomplete scan.`)
        return { items, next: next || undefined, metadata }
      }
      if (request.boundary(items, metadata.hasMore)) return { items, next: undefined, metadata }
      if (!next) throw new Error('Slack empty page did not provide a new continuation.')
      return { items, next, metadata }
    },
  })
}

async function* selectConversations(pages: CollectionPages<SlackEntity>, selected: readonly string[] | undefined): CollectionPages<SlackEntity> {
  const missing = new Set(selected)
  for await (const page of pages) {
    const channels = selected === undefined ? page.items : page.items.filter((channel) => selected.includes(channel.id))
    for (const channel of channels) missing.delete(channel.id)
    yield { ...page, items: channels }
  }
  for (const id of missing) {
    throw new Error(`Configured Slack channel "${id}" was not found or is not accessible for conversationTypes.`)
  }
}

async function readPayload(method: Method, response: Response): Promise<SlackPayload> {
  const payload = envelope.parse(await response.json())
  if (payload.ok || payload.error === 'invalid_cursor') return payload
  const code = payload.error ?? 'unknown_error'
  if (code === 'ratelimited' || code === 'rate_limited') throw HttpError.withStatus(response, 429, { body: JSON.stringify({ error: code }), retryAfterMs: 60_000 })
  if (transientErrors.has(code)) throw HttpError.withStatus(response, 503, { body: JSON.stringify({ error: code }) })
  const needed = payload.needed ? ` Required scopes: ${payload.needed}.` : ''
  const repliesHint = method === 'conversations.replies' ? ' Disable includeReplies explicitly for history-only reads.' : ''
  throw new Error(`Slack ${method} failed (${code}).${needed} Check the token, resource scopes, and conversation access.${repliesHint}`)
}

import { z } from 'zod'

const pageSize = z.int().min(1).max(999)
const missingToken = 'Set SLACK_API_TOKEN or pass token.'
const token = z.string().optional().pipe(z.string({ error: missingToken }).trim().min(1, missingToken))

const slackConfigSchema = z.object({
  /** Stable, non-secret installation identity. Changing it creates new stream identities. */
  sourceId: z.string(),
  database: z.string(),
  tablePrefix: z.string(),
  /** Undefined selects every conversation returned for conversationTypes; otherwise use IDs. */
  channels: z.array(z.string()).readonly().optional(),
  conversationTypes: z.array(z.enum(['public_channel', 'private_channel', 'im', 'mpim'])).min(1).readonly(),
  includeReplies: z.boolean(),
  pageSize,
  messagePageSize: pageSize,
  /** Optional bootstrap lower bound; undefined starts with the recent overlap window. */
  historyFrom: z.string().regex(/^\d+\.\d{1,6}$/, 'must be an exact decimal Slack timestamp with at most six fractional digits').optional(),
  overlapMs: z.int().min(0),
  /** Slack OAuth token; read when a stream runs, never by schema commands. */
  token,
})

export type SlackConfig = z.input<typeof slackConfigSchema>

/** Runtime reader settings; destination names are defined when the schemas load. */
export const slackReaderConfigSchema = slackConfigSchema.omit({ database: true, tablePrefix: true })
export type SlackReaderConfig = z.input<typeof slackReaderConfigSchema>

// Keep these values stable across runs.
export const slackConfig: SlackConfig = {
  sourceId: 'slack.primary',
  database: 'default',
  tablePrefix: 'slack',
  channels: undefined,
  conversationTypes: ['public_channel'],
  includeReplies: true,
  pageSize: 200,
  // Commercially distributed apps outside the Slack Marketplace get 15 messages per page.
  messagePageSize: 15,
  historyFrom: undefined,
  overlapMs: 86_400_000,
  token: process.env.SLACK_API_TOKEN,
}

import { definePipeline, defineStream } from '@chkit/plugin-ingest'

import { slackConfig, type SlackReaderConfig } from './config.js'
import { readChannels, slackChannelsRaw } from './sources/channels.js'
import { readUsers, slackUsersRaw } from './sources/users.js'
import { readMessages, slackMessagesRaw } from './sources/messages.js'
import { slackMessageStrategy } from './state.js'

// One installation pipeline, with independent streams for the three resource types.
// Destination names come from config.ts when the raw schemas load.
export function createSlackPipeline(config: SlackReaderConfig = slackConfig) {
  const boundConfig = { ...config, channels: config.channels ? [...config.channels] : undefined, conversationTypes: [...config.conversationTypes] }
  return definePipeline({
    id: boundConfig.sourceId,
    tags: ['provider:slack'],
    maxStreams: 1,
    maxFetches: 1,
    maxLoads: 1,
    streams: [
      defineStream({ batchSize: 500, id: `${boundConfig.sourceId}.channels`, tags: ['resource:channels'], destination: slackChannelsRaw, read: (context) => readChannels(context, boundConfig) }),
      defineStream({ batchSize: 500, id: `${boundConfig.sourceId}.users`, tags: ['resource:users'], destination: slackUsersRaw, read: (context) => readUsers(context, boundConfig) }),
      defineStream({ batchSize: 1, id: `${boundConfig.sourceId}.messages`, tags: ['resource:messages'], destination: slackMessagesRaw, incremental: slackMessageStrategy, read: (context) => readMessages(context, boundConfig) }),
    ],
  })
}

export const slack = createSlackPipeline()

import { rawRows, rawTable, type SourceContext } from '@chkit/plugin-ingest'

import { createSlackClient } from '../client.js'
import { slackConfig, type SlackReaderConfig } from '../config.js'

export const slackChannelsRaw = rawTable({ database: slackConfig.database, name: `${slackConfig.tablePrefix}_channels_raw` })

export async function* readChannels(context: SourceContext, config: SlackReaderConfig) {
  const client = createSlackClient(context, config)
  const { sourceId } = client.settings
  const teamId = await client.workspace()
  for await (const page of client.conversations()) {
    yield { rows: rawRows(page.items.map((data) => ({ source_id: sourceId, team_id: teamId, data })), ({ data }) => JSON.stringify([sourceId, 'channels', teamId, data.id])) }
  }
}

import { rawRows, rawTable, type SourceContext } from '@chkit/plugin-ingest'

import { createSlackClient } from '../client.js'
import { slackConfig, type SlackReaderConfig } from '../config.js'

export const slackUsersRaw = rawTable({ database: slackConfig.database, name: `${slackConfig.tablePrefix}_users_raw` })

export async function* readUsers(context: SourceContext, config: SlackReaderConfig) {
  const client = createSlackClient(context, config)
  const { sourceId } = client.settings
  const teamId = await client.workspace()
  for await (const page of client.users()) {
    yield { rows: rawRows(page.items.map((data) => ({ source_id: sourceId, team_id: teamId, data })), ({ data }) => JSON.stringify([sourceId, 'users', teamId, data.id])) }
  }
}

import { rawRows, rawTable, type ReadContext, type SourceChunk, type RawRow } from '@chkit/plugin-ingest'

import { createSlackClient, type MessageMethod, type SlackClient, type SlackMessage } from '../client.js'
import { slackConfig, type SlackReaderConfig } from '../config.js'
import { formatTimestamp, messageScope, timestampMicros, type SlackMessageSelection, type SlackMessageState } from '../state.js'

export const slackMessagesRaw = rawTable({ database: slackConfig.database, name: `${slackConfig.tablePrefix}_messages_raw` })

/** Temporary API cursors never enter the checkpoint; exact timestamps survive expiration. */
export async function* readMessages(
  context: ReadContext<SlackMessageSelection, SlackMessageState>,
  config: SlackReaderConfig,
): AsyncGenerator<SourceChunk<RawRow, SlackMessageState>> {
  const client = createSlackClient(context, config)
  const settings = client.settings
  const to = context.selection.to
  const initialFrom = context.selection.from ?? settings.historyFrom ?? formatTimestamp(max(0n, timestampMicros(to) - BigInt(settings.overlapMs) * 1_000n))
  const from = context.selection.from ?? (context.state ? formatTimestamp(max(settings.historyFrom === undefined ? 0n : timestampMicros(settings.historyFrom), timestampMicros(context.state.watermark) - BigInt(settings.overlapMs) * 1_000n)) : initialFrom)
  if (!context.state?.active && timestampMicros(from) > timestampMicros(to)) throw new Error('Slack selection starts after its cutoff.')
  const teamId = await client.workspace()
  const scope = messageScope(teamId, settings)
  if (context.state && context.state.scope !== scope) throw new Error('Slack checkpoint belongs to a different workspace or query. Restore the configuration or use a distinct sourceId.')
  let state: SlackMessageState = context.state ?? { scope, watermark: initialFrom }
  if (!state.active) {
    const channels = new Set<string>()
    for await (const page of client.conversations()) {
      for (const channel of page.items) channels.add(channel.id)
    }
    state = { ...state, active: { from, to, channels: [...channels].sort(), channelIndex: 0, latest: formatTimestamp(timestampMicros(to) + 1n),
      requestedFrom: context.selection.from, requestedTo: context.selection.requestedTo } }
    yield marker(state, 'window-open')
  } else if (context.selection.backfill && (context.selection.from !== state.active.requestedFrom || context.selection.requestedTo !== state.active.requestedTo)) {
    throw new Error('Slack backfill bounds changed while a window is unfinished. Resume the original range or use a new backfill ID.')
  }

  while (state.active && state.active.channelIndex < state.active.channels.length) {
    context.signal.throwIfAborted()
    const work = state.active
    const channelId = work.channels[work.channelIndex]
    if (!channelId) throw new Error('Slack checkpoint has no current channel.')
    const page = await readTimePage(client, { channel: channelId, oldest: formatTimestamp(max(0n, timestampMicros(work.from) - 1n)), latest: work.latest,
      inclusive: 'false', include_all_metadata: 'true' }, 'conversations.history')
    assertRange(page.items, timestampMicros(work.from), timestampMicros(work.latest) - 1n)
    const latest = page.items.length ? formatTimestamp(page.items.reduce((oldest, item) => min(oldest, timestampMicros(item.ts)), timestampMicros(work.latest))) : work.latest
    if (page.hasMore && (page.items.length === 0 || timestampMicros(latest) >= timestampMicros(work.latest))) throw new Error('Slack history pagination has no safe timestamp progress.')
    const roots = settings.includeReplies ? page.items.filter((item) => (item.reply_count ?? 0) > 0).map((item) => item.thread_ts ?? item.ts) : []
    if (page.items.length) yield { rows: messageRows(page.items, settings.sourceId, teamId, channelId) }
    for (const root of new Set(roots)) {
      let after = formatTimestamp(max(0n, timestampMicros(root) - 1n))
      while (true) {
        const replies = await readTimePage(client, { channel: channelId, ts: root, oldest: after,
          latest: formatTimestamp(timestampMicros(work.to) + 1n), inclusive: 'false', include_all_metadata: 'true' }, 'conversations.replies')
        const children = replies.items.filter((item) => item.ts !== root)
        assertRange(children, timestampMicros(after) + 1n, timestampMicros(work.to))
        if (replies.hasMore && children.length === 0) throw new Error('Slack thread pagination has no safe timestamp progress.')
        if (replies.items.length) yield { rows: messageRows(replies.items, settings.sourceId, teamId, channelId) }
        if (!replies.hasMore) break
        after = formatTimestamp(children.reduce((frontier, item) => max(frontier, timestampMicros(item.ts)), timestampMicros(after)))
      }
    }
    // Only a fully read history page and all its replies may advance durable history.
    context.signal.throwIfAborted()
    state = { ...state, active: { ...work, channelIndex: work.channelIndex + (page.hasMore ? 0 : 1),
      latest: page.hasMore ? latest : formatTimestamp(timestampMicros(work.to) + 1n) } }
    yield marker(state, 'history-page-complete')
  }
  if (state.active) {
    state = { scope, watermark: formatTimestamp(max(timestampMicros(state.watermark), timestampMicros(state.active.to))) }
    yield marker(state, 'window-complete')
  }
}

/** Empty cursor pages use the live cursor; nonempty pages establish timestamp boundaries. */
async function readTimePage(client: SlackClient, query: Record<string, string>, method: MessageMethod): Promise<{ items: SlackMessage[]; hasMore: boolean }> {
  let restarted = false
  const parents = new Map<string, SlackMessage>()
  while (true) {
    let continued = false
    for await (const page of client.messages(method, query)) {
      if (page.metadata?.cursorExpired) {
        if (!continued || restarted) throw new Error(`Slack ${method} pagination cursor expired.`)
        restarted = true
        break
      }
      for (const item of page.items) parents.set(item.ts, item)
      if (page.next === undefined) return { items: [...parents.values()], hasMore: page.metadata?.hasMore === true }
      continued = true
    }
  }
}

function messageRows(items: readonly SlackMessage[], sourceId: string, teamId: string, channelId: string): RawRow[] {
  return rawRows(items.map((data) => ({ source_id: sourceId, team_id: teamId, channel_id: channelId, data })), ({ data }) => JSON.stringify([sourceId, 'messages', teamId, channelId, data.ts]))
}
function marker(state: SlackMessageState, id: string): SourceChunk<RawRow, SlackMessageState> {
  // State-only boundaries flush previous rows without assigning identity to mutable data.
  return { rows: [], state, id }
}
function assertRange(items: SlackMessage[], from: bigint, to: bigint): void {
  if (items.some((item) => {
    const ts = timestampMicros(item.ts)
    return ts < from || ts > to
  })) throw new Error('Slack returned a message outside the requested timestamp interval.')
}
function max(left: bigint, right: bigint): bigint { return left > right ? left : right }
function min(left: bigint, right: bigint): bigint { return left < right ? left : right }

import { describe, expect, test } from 'bun:test'

import { HttpError, definePipeline, runIngestion, selectStreams, type PipelineDefinition, type ReadContext } from '@chkit/plugin-ingest'
import { createMemoryDestination, createMemoryJournal, createReadContext } from '@chkit/plugin-ingest/testing'

import { createSlackClient } from '../client.js'
import type { SlackReaderConfig } from '../config.js'
import * as definitions from '../index.js'
import { createSlackPipeline, slack } from '../pipeline.js'
import { readChannels } from '../sources/channels.js'
import { readMessages } from '../sources/messages.js'
import { messageScope, parseMessageState, slackMessageStrategy, type SlackMessageSelection, type SlackMessageState } from '../state.js'
import { channel, fixture, fixtureConfig, parentMessage, replyMessage, slackEnv, standaloneMessage, user } from './fixtures.js'

const fixtureNow = () => new Date('2023-11-15T00:00:00Z')
const retry = { retries: 1, minTimeout: 0, maxTimeout: 0, randomize: false }

describe('Slack raw template', () => {
  test('exports three raw destinations and checkpointed messages without credentials', () => {
    const exported = Object.values(definitions)
    expect(exported).toContain(slack)
    expect(slack.streams).toHaveLength(3)
    expect(slack.streams.map((stream) => stream.destination.name)).toEqual(['slack_channels_raw', 'slack_users_raw', 'slack_messages_raw'])
    for (const stream of slack.streams) {
      expect(exported).toContain(stream.destination)
      expect(stream.incremental.id).toBe(stream.id.endsWith('.messages') ? 'slack.message-ranges' : 'chkit.full_sync')
    }
    expect(selectStreams([slack], ['provider:slack', 'resource:messages']).map(({ stream }) => stream.id)).toEqual(['slack.primary.messages'])
  })

  test('a pipeline binds installation identity, reader settings, and its token independently of later config edits', async () => {
    const config = { ...fixtureConfig, sourceId: 'slack.secondary', channels: ['C1'], conversationTypes: ['public_channel'] as const,
      includeReplies: false, pageSize: 37, messagePageSize: 12, historyFrom: '1699999999.000000', token: 'secondary-token' }
    const expectedScope = messageScope('T1', config)
    const requests: Array<{ url: URL; authorization: string | null }> = []
    const env = slackEnv((url, init) => { requests.push({ url, authorization: new Headers(init?.headers).get('Authorization') }); return fixture(url) })
    const pipeline = createSlackPipeline(config)
    config.sourceId = 'changed'
    config.channels.push('missing')
    config.historyFrom = 'invalid'
    config.token = 'changed'
    const journal = createMemoryJournal(), destination = createMemoryDestination()
    const result = await runIngestion(request(pipeline), { ...env, now: fixtureNow, journal, destination })
    expect(result.ok, JSON.stringify(result)).toBe(true)
    expect(result.streams.map((stream) => stream.streamId)).toEqual(['slack.secondary.channels', 'slack.secondary.users', 'slack.secondary.messages'])
    expect(parseMessageState((await journal.readCheckpoint('slack.secondary.messages')).envelope?.state).scope).toBe(expectedScope)
    expect(destination.tables.get('default.slack_messages_raw')?.[0]?.id).toBe(JSON.stringify(['slack.secondary', 'messages', 'T1', 'C1', parentMessage.ts]))
    expect(destination.tables.get('default.slack_users_raw')?.[0]?.raw).toMatchObject({ source_id: 'slack.secondary' })
    const urls = requests.map((entry) => entry.url)
    expect(urls.filter((url) => url.pathname === '/api/conversations.list' || url.pathname === '/api/users.list').every((url) => url.searchParams.get('limit') === '37')).toBe(true)
    expect(urls.find((url) => url.pathname === '/api/conversations.history')?.searchParams.get('limit')).toBe('12')
    expect(urls.find((url) => url.pathname === '/api/conversations.history')?.searchParams.get('oldest')).toBe('1699999998.999999')
    expect(urls.some((url) => url.pathname === '/api/conversations.replies')).toBe(false)
    expect(requests.every((entry) => entry.authorization === 'Bearer secondary-token')).toBe(true)
  })

  test('a failed resource leaves the other resource streams selectable and able to commit', async () => {
    const env = slackEnv((url) => url.pathname === '/api/users.list'
      ? Response.json({ ok: false, error: 'missing_scope', needed: 'users:read' }) : fixture(url))
    const pipeline = createSlackPipeline(fixtureConfig)
    const journal = createMemoryJournal(), destination = createMemoryDestination()
    const result = await runIngestion(request(pipeline), { ...env, now: fixtureNow, journal, destination })
    expect(result.ok).toBe(false)
    expect(result.streams.map((stream) => stream.outcome)).toEqual(['succeeded', 'failed', 'succeeded'])
    expect(destination.tables.has('default.slack_channels_raw')).toBe(true)
    expect(destination.tables.has('default.slack_users_raw')).toBe(false)
    expect(destination.tables.has('default.slack_messages_raw')).toBe(true)
    expect(parseMessageState((await journal.readCheckpoint('slack.primary.messages')).envelope?.state).active).toBeUndefined()
    expect((await journal.readCheckpoint('slack.primary.users')).envelope).toBeUndefined()
    expect(selectStreams([pipeline], ['resource:users']).map(({ stream }) => stream.id)).toEqual(['slack.primary.users'])
  })

  test('messages run before metadata streams and replay an unfinished page independently', async () => {
    const calls: string[] = []
    const env = slackEnv((url) => { calls.push(url.pathname); return fixture(url) })
    const pipeline = createSlackPipeline(fixtureConfig)
    const limited = { ...pipeline, streams: pipeline.streams.map((stream) => ({ ...stream, budget: { ...stream.budget, maxChunks: 2 } })) }
    const journal = createMemoryJournal(), destination = createMemoryDestination()
    const first = await runIngestion({ selected: selectStreams([limited], ['resource:messages']), backfill: undefined }, { ...env, now: fixtureNow, journal, destination })
    expect(first.streams[0]?.outcome).toBe('budget_exhausted')
    const pending = await journal.readCheckpoint('slack.primary.messages')
    expect(parseMessageState(pending.envelope?.state).active?.latest).toBe('1700006400.000001')
    expect(parseMessageState(pending.envelope?.state).active).not.toHaveProperty('threads')
    expect(destination.tables.has('default.slack_channels_raw')).toBe(false)
    expect(destination.tables.has('default.slack_users_raw')).toBe(false)
    expect((await journal.readCheckpoint('slack.primary.channels')).version).toBe(0)
    expect((await journal.readCheckpoint('slack.primary.users')).version).toBe(0)
    calls.length = 0
    expect((await runIngestion({ selected: selectStreams([pipeline], ['resource:users']), backfill: undefined }, { ...env, now: fixtureNow, journal, destination })).ok).toBe(true)
    expect(calls).toEqual(['/api/auth.test', '/api/users.list'])
    expect(await journal.readCheckpoint('slack.primary.messages')).toEqual(pending)
    calls.length = 0
    expect((await runIngestion({ selected: selectStreams([pipeline], ['resource:messages']), backfill: undefined }, { ...env, now: fixtureNow, journal, destination })).ok).toBe(true)
    expect(calls).toEqual(['/api/auth.test', '/api/conversations.history', '/api/conversations.replies'])
    expect(destination.tables.get('default.slack_messages_raw')?.map((row) => row.raw)).toContainEqual({ source_id: 'slack.primary', team_id: 'T1', channel_id: 'C1', data: replyMessage })
    expect((await journal.readCheckpoint('slack.primary.channels')).version).toBe(0)
  })

  test('every stream preserves provider payloads and reruns publish edits under stable identities', async () => {
    let changed = false
    const env = slackEnv((url) => url.pathname === '/api/conversations.history' && changed
      ? Response.json({ ok: true, messages: [{ ...parentMessage, text: 'Edited discussion' }, standaloneMessage], response_metadata: { next_cursor: '' } })
      : fixture(url))
    const journal = createMemoryJournal()
    const destination = createMemoryDestination()
    const selected = request(fixturePipeline())
    const first = await runIngestion(selected, { ...env, now: fixtureNow, journal, destination, retry })
    expect(first.ok, JSON.stringify(first)).toBe(true)
